class Solution:
    def checkEquivalence(self, root1: 'Node', root2: 'Node') -> bool:
        def leaves(root):
            out, stack = [], [root]
            while stack:
                node = stack.pop()
                if node.val == '+':
                    stack.append(node.left)
                    stack.append(node.right)
                else:
                    out.append(node.val)
            return out
        return sorted(leaves(root1)) == sorted(leaves(root2))

