class Solution {
public:
    bool checkEquivalence(Node* root1, Node* root2) {
        string a = leaves(root1), b = leaves(root2);
        sort(a.begin(), a.end());
        sort(b.begin(), b.end());
        return a == b;
    }
private:
    string leaves(Node* node) {
        string out;
        vector<Node*> st{node};
        while (!st.empty()) {
            Node* cur = st.back();
            st.pop_back();
            if (cur->val == '+') {
                st.push_back(cur->left);
                st.push_back(cur->right);
            } else {
                out += cur->val;
            }
        }
        return out;
    }
}

