class Solution {
    public boolean checkEquivalence(Node root1, Node root2) {
        char[] a = leaves(root1), b = leaves(root2);
        Arrays.sort(a);
        Arrays.sort(b);
        return Arrays.equals(a, b);
    }

    private char[] leaves(Node root) {
        StringBuilder sb = new StringBuilder();
        Deque<Node> st = new ArrayDeque<>();
        st.push(root);
        while (!st.isEmpty()) {
            Node cur = st.pop();
            if (cur.val == '+') {
                st.push(cur.left);
                st.push(cur.right);
            } else {
                sb.append(cur.val);
            }
        }
        return sb.toString().toCharArray();
    }
}

