var checkEquivalence = function(root1, root2) {
    const leaves = (root) => {
        const out = [], st = [root];
        while (st.length) {
            const cur = st.pop();
            if (cur.val === '+') {
                st.push(cur.left);
                st.push(cur.right);
            } else {
                out.push(cur.val);
            }
        }
        return out.sort().join('');
    };
    return leaves(root1) === leaves(root2);
};

