var checkEquivalence = function(root1, root2) {
    const collect = (node, cnt) => {
        if (!node) return;
        if (node.val === '+') {
            collect(node.left, cnt);
            collect(node.right, cnt);
        } else {
            cnt[node.val.charCodeAt(0) - 97]++;
        }
    };
    const a = new Array(26).fill(0), b = new Array(26).fill(0);
    collect(root1, a);
    collect(root2, b);
    for (let i = 0; i < 26; i++)
        if (a[i] !== b[i]) return false;
    return true;
};
